const item = $input.first();
const file = item.binary?.attachment;

if (!file) throw new Error('No uploaded attachment found');

const mime = file.mimeType;
if (!['image/png', 'image/jpeg', 'image/webp'].includes(mime)) {
  throw new Error(`Unsupported image type: ${mime}`);
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'attachment');

return [{
  json: {
    ...item.json,
    image_data_url: `data:${mime};base64,${buffer.toString('base64')}`,
  },
  binary: item.binary,
}];

