const r=$input.first().json;
const text=r.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('\n')||'';
if(!text)throw new Error('Gemini vision returned no text');
return [{json:{model:'gemini-3.8-flash',message:{role:'assistant',content:text}}}];

const r=$input.first().json;
const text=r.choices?.[0]?.message?.content;
if(typeof text!=='string'||!text.trim())throw new Error('OpenAI vision returned no text');
return [{json:{model:'gpt-4o-mini',message:{role:'assistant',content:text}}}];

const input=$input.first().json;
const categoryPairs=[['network & vpn','network_vpn'],['network_vpn','network_vpn'],['authentication & access','auth_access'],['auth_access','auth_access'],['email & communication','email_communication'],['email_communication','email_communication'],['software & applications','software_apps'],['software_apps','software_apps'],['system & os','system_os'],['system_os','system_os'],['other / out of scope','other'],['other','other']];
const categories=new Map(categoryPairs);
const labels={'vpn authentication failure':'vpn_auth_failure','vpn connection failure':'vpn_connection_failure','wi-fi connectivity issue':'wifi_connectivity','wifi connectivity issue':'wifi_connectivity','dns/network configuration error':'dns_network_config','internet connection problem':'internet_connection','wrong/expired password':'wrong_expired_password','account locked':'account_locked','mfa/authentication failure':'mfa_failure','permission denied':'permission_denied','access to restricted resource':'restricted_resource_access','cannot send email':'cannot_send_email','cannot receive email':'cannot_receive_email','email authentication failure':'email_auth_failure','mailbox/storage full':'mailbox_full','email client configuration problem':'email_client_config','application wont launch':'app_wont_launch','application crash':'app_crash','installation failure':'installation_failure','application configuration error':'app_config_error','software update failure':'software_update_failure','windows/system error':'system_error','driver problem':'driver_problem','os update failure':'os_update_failure','system performance issue':'performance_issue','hardware-related error':'hardware_error','out of scope':'out_of_scope'};
const defaults={network_vpn:'vpn_auth_failure',auth_access:'wrong_expired_password',email_communication:'cannot_send_email',software_apps:'app_wont_launch',system_os:'system_error',other:'out_of_scope'};
function parse(raw){
 const text=String(raw||'').trim();if(!text)return {vision:null,raw_text:'',parsed:false};
 const lines=text.split(/\r?\n/);
 const labels=['application or operating system','error message(s)','error codes','state of screen'];
 const header=line=>labels.some(x=>line.trim().toLowerCase().startsWith(x+':'));
 const find=name=>lines.findIndex(x=>x.trim().toLowerCase().startsWith(name+':'));
 const content=index=>{
  if(index<0)return [];
  const rest=lines[index].slice(lines[index].indexOf(':')+1).trim();
  const following=lines.slice(index+1),end=following.findIndex(header);
  const section=end<0?following:following.slice(0,end);
  return [rest,...section].map(x=>x.trim()).filter(Boolean);
 };
 const appIndex=find('application or operating system'),errorIndex=find('error message(s)'),codeIndex=find('error codes'),stateIndex=find('state of screen');
 const recognized=appIndex>=0||errorIndex>=0||codeIndex>=0||stateIndex>=0;
 const firstValue=index=>index<0?null:lines[index].slice(lines[index].indexOf(':')+1).trim();
 const clean=value=>!value||/^(not visible|none|n\/a|unknown)\.?$/i.test(value)?null:value;
 const messages=content(errorIndex,'error message(s)').map(x=>x.replace(/^[-*]\s*/,'').replace(/"/g,'').trim()).filter(Boolean);
 const errorText=messages.length?messages.join('; '):null;
 const codes=content(codeIndex,'error codes').join(' ').trim();
 const state=content(stateIndex,'state of screen').join(' ').trim();
 const app=clean(firstValue(appIndex)),code=clean(codes||firstValue(codeIndex));
 const unreadable=/unreadable|not readable/i.test(text);
 const found=Boolean(app||errorText||code||state);
 const observation=state||(!recognized?text:null);
 return {raw_text:text,parsed:recognized,vision:{usable:Boolean(recognized&&found&&!unreadable),image_quality:unreadable?'poor':(found?'good':'unknown'),application:app,error_text:errorText||(!recognized?text:null),error_code:code,observations:observation?[observation]:[],contradictions:[],confidence:errorText?0.8:0.5,parse_ok:recognized}};
}
const parsed=parse(input.vision_description||'');
const category=categories.get(String(input.category||'').trim().toLowerCase())||'other';
const label=String(input.subcategory||'').trim().toLowerCase().replace(/'/g,'');
const subcategory=labels[label]||defaults[category];
const title=String(input.title||'').trim(),description=String(input.description||'').trim();
return [{json:{request_id:input.request_id||null,title,description,user_text:[title,description].filter(Boolean).join('\n'),language:input.language||null,vision:parsed.vision,vision_raw_text:parsed.raw_text,vision_model:input.vision_model||'none',classifier_hint:{category,subcategory,confidence:Number(input.confidence)||0},classifier_confidence:Number(input.confidence)||0,triage:{category,subcategory,urgency:'medium',confidence:Number(input.confidence)||0,search_query:'',is_sensitive:false,needs_clarification:false,language:input.language||null}}}];

const base=$input.first().json;
const cats={network_vpn:['vpn_auth_failure','vpn_connection_failure','wifi_connectivity','dns_network_config','internet_connection'],auth_access:['wrong_expired_password','account_locked','mfa_failure','permission_denied','restricted_resource_access'],email_communication:['cannot_send_email','cannot_receive_email','email_auth_failure','mailbox_full','email_client_config'],software_apps:['app_wont_launch','app_crash','installation_failure','app_config_error','software_update_failure'],system_os:['system_error','driver_problem','os_update_failure','performance_issue','hardware_error'],other:['out_of_scope']};
const patterns=[/\bhack(?:ed|ing)?\b/i,/compromis(?:ed|e)|pirat(?:ed|age)/i,/phishing|hame[cç]onn/i,/ransomware|ran[cç]ongiciel/i,/malware|trojan|virus/i,/data (?:leak|breach)/i,/stolen (?:laptop|phone|device)/i,/unauthori[sz]ed (?:access|login)/i,/unexpected (?:mfa|multi.factor) (?:prompt|approval)/i,/suspicious (?:login|activity)/i,/password.{0,20}(?:leak|exposed|stolen)/i,/api.?key|access token.{0,20}(?:leak|exposed)/i];
const text=[base.user_text,base.vision_raw_text].join('\n'),hit=patterns.find(p=>p.test(text));
const g=base.triage||{},category=cats[g.category]?g.category:'other';
const subcategory=cats[category].includes(g.subcategory)?g.subcategory:(category==='other'?'out_of_scope':cats[category][0]);
const confidence=Math.max(0,Math.min(1,Number(g.confidence)||0));
const vague=base.user_text.trim().length<18||/^(help|broken|not working|it doesn't work|ça ne marche pas)[.! ]*$/i.test(base.user_text.trim());
const reliable=category!=='other'&&confidence>=0.7;
const sensitive=Boolean(g.is_sensitive)||Boolean(hit);
const language=['en','fr'].includes(String(g.language||'').toLowerCase())?g.language:(base.language||'en');
const triage={...g,category,subcategory,confidence,language,is_sensitive:sensitive,
 urgency:sensitive?(/ransomware|data (?:leak|breach)|account.{0,20}(?:hack|compromis)|\bhack(?:ed|ing)?\b/i.test(text)?'critical':'high'):(['low','medium','high','critical'].includes(g.urgency)?g.urgency:'medium'),
 needs_clarification:Boolean(g.needs_clarification)||(!reliable&&vague)||(!base.vision?.usable&&/unreadable|not readable/i.test(base.vision_raw_text||'')),
 search_query:String(g.search_query||[base.user_text,base.vision?.error_text,base.vision?.application].filter(Boolean).join(' ')),
 sensitivity_reason:hit?'Forced by deterministic security keyword':g.sensitivity_reason||null};
const route_action=sensitive?'ticket':triage.needs_clarification?'clarify':reliable?'answer':'ticket';
return [{json:{...base,triage,route_action,category_reliable:reliable,security_keyword:hit?hit.source:null}}];

const points=$input.first().json.chunks||[],r=$('Route Safety & Confidence').first().json;
const enough=points.filter(p=>Number(p.score)>=0.48).length>=2,top=points.length>0&&points[0].category===r.triage.category;
return [{json:{...r,retrieval:{query:$('Build retrieval input (1)').first().json.query,chunks:points,attempts:1},relevance_ok:enough&&top,relevance_reason:!enough?'fewer than two passages scored >=0.48':'top-1 category differs from Triage'}}];

const r=$('Check relevance (1)').first().json,err=r.vision?.error_text;
const query=[r.triage.search_query,err?`error "${err}" troubleshooting`:'specific error troubleshooting'].filter(Boolean).join(' ').replace(/\s+/g,' ').trim();
return [{json:{query,category:r.triage.category,top_k:5}}];

const points=$input.first().json.chunks||[],r=$('Route Safety & Confidence').first().json;
const enough=points.filter(p=>Number(p.score)>=0.48).length>=2,top=points.length>0&&points[0].category===r.triage.category;
return [{json:{...r,retrieval:{query:$('Build retrieval input (2)').first().json.query,chunks:points,attempts:2},relevance_ok:enough&&top,relevance_reason:!enough?'fewer than two passages scored >=0.48':'top-1 category differs from Triage'}}];

const v=$input.first().json,d=v.sanitized_dossier;
if(!d)throw new Error('Validator returned no sanitized ticket dossier');
return [{json:{...d,feedback_for_stage:v.feedback_for_stage||v.reason||'Regenerate a complete secret-free ticket.',attempt_counts:{...d.attempt_counts,regenerate:1,total:(d.attempt_counts?.total||0)+1}}}];

const v=$input.first().json,d=v.sanitized_dossier;
if(!d||d.mode!=='ticket'||!d.draft_ticket)throw new Error('Approved ticket dossier is missing');
const t=d.draft_ticket,requestId=String(d.request_id||'unknown');
const priorityIds={critical:'1',high:'2',medium:'3',low:'4'};
const priority=String(t.priority||'');
if(!priorityIds[priority])throw new Error(`Unsupported ticket priority: ${priority}`);
const safeReason=String(v.reason||'Approved by the final Validator.')
 .replace(/\b(password|passwd|pwd|secret|api[_ -]?key|access[_ -]?token|client[_ -]?secret)\b(\s*[:=]\s*)[^\s,;]+/gi,'$1$2[REDACTED]')
 .replace(/\bBearer\s+[A-Za-z0-9._~+/=-]{12,}/gi,'Bearer [REDACTED]');
const description=t.description.replace(/(Reason for Escalation\n)([\s\S]*?)(\n\nSuggested Assignee Group: IT Support)/,
  `$1$2\n\nValidator verdict: ${String(v.verdict||'approve')}\nValidator reason: ${safeReason}$3`);
return [{json:{summary:t.title,description,priority, jira_priority_id:priorityIds[priority],request_id:requestId}}];

const result=$input.first().json,d=result.sanitized_dossier||{},c=d.attempt_counts||{};
let action='ticket';
if(result.verdict==='approve')action='approve';
else if(result.verdict==='clarify')action='clarify';
else if(result.verdict==='retry_retrieval'&&Number(c.retry_retrieval||0)<1&&Number(c.total||0)<2)action='retry_retrieval';
else if(result.verdict==='regenerate'&&Number(c.regenerate||0)<1&&Number(c.total||0)<2)action='regenerate';
return [{json:{...result,workflow_action:action}}];

const result=$input.first().json,d=result.sanitized_dossier;
if(!d)throw new Error('Validator retry lacks sanitized dossier');
const query=[d.retrieval?.query||d.triage?.search_query||d.user_text,String(result.feedback_for_stage||'').slice(0,240),'specific error troubleshooting'].filter(Boolean).join(' ');
return [{json:{query,category:d.triage.category,top_k:5,context:d}}];

const response=$input.first().json,req=$('Build validator retry retrieval').first().json,chunks=response.chunks||[];
const ok=chunks.filter(c=>Number(c.score)>=0.48).length>=2&&chunks.length>0&&chunks[0].category===req.category;
return [{json:{...req.context,retrieval:{query:req.query,chunks,attempts:2},relevance_ok:ok}}];

const v=$input.first().json,d=v.sanitized_dossier;
if(!d)throw new Error('Regeneration lacks sanitized dossier');
return [{json:{...d,feedback_for_stage:v.feedback_for_stage||v.reason,attempt_counts:{...d.attempt_counts,regenerate:(d.attempt_counts?.regenerate||0)+1,total:(d.attempt_counts?.total||0)+1}}}];
